package netutil

import (
	"context"
	"errors"
	"net"
	"net/http"
)

// Error applies no-store only to errors generated by this proxy. Forwarded
// site responses, including cacheable error pages, keep their own policy.
func Error(w http.ResponseWriter, message string, status int) {
	w.Header().Set("Cache-Control", "no-store")
	http.Error(w, message, status)
}

// ProxyErrorStatus classifies local transport errors consistently for content,
// next-hop HTTP and CONNECT. A cancellation may carry a timeout cause even when
// the resulting socket error is only net.ErrClosed or context.Canceled.
func ProxyErrorStatus(ctx context.Context, err error) int {
	var timeout net.Error
	if errors.Is(err, context.DeadlineExceeded) || errors.Is(context.Cause(ctx), context.DeadlineExceeded) || (errors.As(err, &timeout) && timeout.Timeout()) {
		return http.StatusGatewayTimeout
	}
	return http.StatusBadGateway
}
